#!/usr/bin/env python3
"""
Sergio Knowledge OS -- Milestone 2 Setup Script

Usage:
    cd ~/Sergio_Knowledge_OS_APP   # or any parent directory
    python3 setup_milestone2.py

This script:
  1. Finds the project root (Sergio_Knowledge_OS_APP)
  2. Creates missing directories
  3. Writes/overwrites ONLY Milestone 2 files
  4. Cleans __pycache__ and .pyc files
  5. Runs pytest and verify_milestone2.py
  6. Prints a final PASS/FAIL report
"""

import base64
import json
import os
import shutil
import subprocess
import sys
from pathlib import Path

# =============================================================================
# EMBEDDED FILES -- Milestone 2 Release (base64 encoded)
# =============================================================================

EMBEDDED_FILES_JSON = '''
{
  "config.yaml": "",
  "requirements.txt": "cHl5YW1sCnB5dGVzdAo=",
  "app/__init__.py": "",
  "app/backend/__init__.py": "",
  "app/backend/importer/__init__.py": "",
  "app/backend/utils/__init__.py": "",
  "tests/__init__.py": "",
  "app/backend/config.py": "",
  "app/backend/utils/hashing.py": "",
  "app/backend/importer/base_parser.py": "",
  "app/backend/importer/import_report.py": "",
  "app/backend/importer/chatgpt_parser.py": "",
  "app/backend/importer/gemini_parser.py": "",
  "app/backend/importer/import_manager.py": "",
  "tests/conftest.py": "",
  "tests/test_config.py": "",
  "tests/test_parsers.py": "",
  "tests/test_import_manager.py": "",
  "tests/fixtures/chatgpt_export.json": "",
  "tests/fixtures/chatgpt_export.html": "",
  "tests/fixtures/gemini_export.json": "",
  "verify_milestone2.py": ""
}'''


def find_project_root() -> Path:
    """Find Sergio_Knowledge_OS_APP in current or parent directories."""
    current = Path.cwd().resolve()
    for path in [current] + list(current.parents):
        candidate = path / "Sergio_Knowledge_OS_APP"
        if candidate.is_dir():
            return candidate
        if path.name == "Sergio_Knowledge_OS_APP":
            return path
    fallback = current / "Sergio_Knowledge_OS_APP"
    print(f"WARNING: Project root not found. Creating: {fallback}")
    return fallback


def write_file(root: Path, relative_path: str, content: bytes) -> None:
    """Write a file, creating parent directories if needed."""
    file_path = root / relative_path
    file_path.parent.mkdir(parents=True, exist_ok=True)
    file_path.write_bytes(content)
    print(f"  OK {relative_path}")


def clean_cache(root: Path) -> None:
    """Remove __pycache__ and .pyc files."""
    removed = 0
    for pycache in root.rglob("__pycache__"):
        if pycache.is_dir():
            shutil.rmtree(pycache)
            removed += 1
    for pyc in root.rglob("*.pyc"):
        pyc.unlink()
        removed += 1
    if removed:
        print(f"  CLEANED {removed} cache items")


def run_tests(root: Path) -> dict:
    """Run pytest and verify_milestone2.py."""
    results = {"pytest": None, "verify": None}

    print("\n  RUNNING pytest...")
    pytest_result = subprocess.run(
        [sys.executable, "-m", "pytest", "tests/", "-v", "--tb=short"],
        cwd=root,
        capture_output=True,
        text=True
    )
    results["pytest"] = pytest_result.returncode == 0
    if pytest_result.returncode == 0:
        passed = pytest_result.stdout.count("PASSED")
        print(f"    PASS pytest: {passed} tests passed")
    else:
        print(f"    FAIL pytest (exit code {pytest_result.returncode})")
        print(pytest_result.stdout[-500:] if len(pytest_result.stdout) > 500 else pytest_result.stdout)

    print("\n  RUNNING verify_milestone2.py...")
    verify_result = subprocess.run(
        [sys.executable, "verify_milestone2.py"],
        cwd=root,
        capture_output=True,
        text=True
    )
    results["verify"] = verify_result.returncode == 0
    if verify_result.returncode == 0:
        print(f"    PASS verify_milestone2.py: 6/6 PASS")
    else:
        print(f"    FAIL verify_milestone2.py")
        print(verify_result.stdout[-800:] if len(verify_result.stdout) > 800 else verify_result.stdout)

    return results


def main() -> int:
    print("=" * 60)
    print("  Sergio Knowledge OS -- Milestone 2 Setup")
    print("=" * 60)

    print("\nFINDING project root...")
    root = find_project_root()
    print(f"   DIR {root}")

    print("\nCLEANING cache...")
    clean_cache(root)

    print("\nWRITING Milestone 2 files...")
    embedded = json.loads(EMBEDDED_FILES_JSON)
    for rel_path, b64_content in embedded.items():
        content = base64.b64decode(b64_content)
        write_file(root, rel_path, content)

    print("\nCHECKING dependencies...")
    try:
        import yaml
        import pytest
        print("   PASS pyyaml and pytest already installed")
    except ImportError:
        print("   INSTALLING pyyaml and pytest...")
        pip_result = subprocess.run(
            [sys.executable, "-m", "pip", "install", "pyyaml", "pytest", "-q"],
            capture_output=True,
            text=True
        )
        if pip_result.returncode == 0:
            print("   PASS Dependencies installed")
        else:
            print("   WARNING pip install failed. Run manually: pip install pyyaml pytest")

    print("\nRUNNING verification tests...")
    results = run_tests(root)

    print("\n" + "=" * 60)
    print("  FINAL REPORT")
    print("=" * 60)

    pytest_ok = results.get("pytest", False)
    verify_ok = results.get("verify", False)

    if pytest_ok and verify_ok:
        print("\n  MILESTONE 2: ALL CHECKS PASSED")
        print("\n  Next steps:")
        print("    1. Copy your real exports to:")
        print(f"       {root}/data/imports/chatgpt/")
        print(f"       {root}/data/imports/gemini/")
        print("    2. Run: python verify_milestone2.py")
        print("    3. When real-data tests pass -> Milestone 2 CLOSED")
        return 0
    else:
        print("\n  SOME CHECKS FAILED")
        if not pytest_ok:
            print("    FAIL pytest")
        if not verify_ok:
            print("    FAIL verify_milestone2.py")
        print("\n  Review errors above and re-run this script.")
        return 1


if __name__ == "__main__":
    sys.exit(main())
